/* =============================================================================
   REG-09 · Bienvenida, usuarios adicionales y acceso al panel
   =============================================================================
   Ningún color literal: todo sale de tokens.css.

   Dos apuntes de tokens, por si el día que se amplíe la paleta se ajustan:

   1. El HTML aprobado usa blanco puro (#fff) para la tarjeta y para el texto
      del botón primario. La paleta no tiene token de blanco puro, así que el
      texto sobre el azul de calibración va con `--bw-warm-cream`, el más
      cercano; y la tarjeta NO pinta fondo propio: el panel de contenido del
      shell ya es blanco y heredarlo es más fiel que teñirlo.
   2. El hover del botón secundario aprobado es #E5E7EB, que en tokens es
      `--bw-line-steel`. Se usa tal cual: es el mismo valor, no uno nuevo.
   ========================================================================== */

/* Hija directa de `.bwcnt` (overflow: hidden): el scroll es de la pantalla. */
.screen {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 52px var(--bw-pad-panel) 56px;
}

/* La tarjeta es la columna de contenido de 520px del HTML aprobado. */
.card {
  width: 100%;
  max-width: 520px;
}

/* ── Pasos del registro ─────────────────────────────────────────────────── */

.steps {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin: 0 0 36px;
  padding: 0;
  list-style: none;
}

.step {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  white-space: nowrap;
}

/* El conector entre pasos lo pinta el propio item: el `<ol>` solo admite `<li>`. */
.step + .step::before {
  content: '';
  width: 16px;
  height: 1px;
  flex-shrink: 0;
  background: var(--bw-line-steel);
}

/* Los cuatro van cerrados, con el mismo estilo: el ADMIN ya pasó por todos. */
.stepDone {
  color: var(--bw-signal-green);
}

.stepDone svg {
  flex-shrink: 0;
}

/* ── Banner de bienvenida ───────────────────────────────────────────────── */

.banner {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 28px;
  padding: 20px 22px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 6px;
  background: var(--bw-tint-oferta);
}

.checkRing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin-top: 1px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
}

.title {
  margin: 0 0 5px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.subtitle strong {
  font-weight: 600;
  color: var(--bw-deep-steel);
}

/* ── Contador de plazas ─────────────────────────────────────────────────── */

.counter {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  padding: 8px 12px;
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  background: var(--bw-surface-mist);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  letter-spacing: var(--bw-ls-label);
}

.counter svg {
  flex-shrink: 0;
  color: var(--bw-input-placeholder);
}

/* ── Pregunta y decisiones ──────────────────────────────────────────────── */

.question {
  margin: 0 0 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.buttons {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.primary,
.secondary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 13px 20px;
  border: none;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s ease, background-color 0.15s ease;
}

.primary {
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
}

.primary:hover:not(:disabled) {
  opacity: 0.9;
}

.secondary {
  background: var(--bw-cold-white);
  color: var(--bw-ink-steel);
}

.secondary:hover:not(:disabled) {
  background: var(--bw-line-steel);
}

/* Mientras `onGoToPanel` está en vuelo los dos quedan fuera de juego. */
.primary:disabled,
.secondary:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.primary:focus-visible,
.secondary:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

/* ── Nota informativa ───────────────────────────────────────────────────── */

.note {
  margin: 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--bw-input-placeholder);
}

.note strong {
  font-weight: 600;
  color: var(--bw-text-secondary);
}

/* ── Estados de carga y error ───────────────────────────────────────────── */

.status {
  margin: 0;
  font-size: 14px;
  color: var(--bw-text-secondary);
}

.alert {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: 14px;
  line-height: 1.5;
}

