import { useEffect, useState } from 'react';
import { fetchSeatsUsed, firstName, welcomeView } from '../../lib/onboarding';
import { errorMessage, type MemberProfile } from '../../lib/session';
import styles from './Welcome.module.css';

interface Props {
  profile: MemberProfile;
  /** Abre FRU (formulario de usuario adicional). No es asíncrono: navega y ya. */
  onAddUser: () => void;
  /** `KEY_ACTIVE` → `ACTIVE`. El wiring sustituye esta pantalla por el panel. */
  onGoToPanel: () => Promise<void>;
}

/** Los cuatro pasos del registro, en orden. Aquí llegan los cuatro cerrados. */
const REGISTRATION_STEPS = ['Solicitud', 'Organización', 'Seguridad', 'Activación'];

/**
 * REG-09 · Bienvenida, usuarios adicionales y acceso al panel.
 *
 * Es la PANTALLA: posee todo el estado y es el único sitio que llama a la red.
 * La única lectura es `fetchSeatsUsed()`, una vez al montar, y de su resultado
 * sale TODO lo que se ve de aquí abajo: `welcomeView` decide el título, la
 * pregunta, el contador y si cabe un usuario más. Esta pantalla no cuenta
 * plazas, no compone títulos y no valida nada por su cuenta.
 *
 * Las otras dos salidas son de ida:
 *
 * - `onAddUser` no es asíncrono: se llama y la navegación a FRU la resuelve el
 *   wiring.
 * - `onGoToPanel` sí lo es, porque el servidor mueve el estado a `ACTIVE`. Su
 *   promesa es lo único que se espera aquí: mientras está en vuelo los dos
 *   botones quedan deshabilitados para que no se disparen dos activaciones, y
 *   tanto si rechaza como si resuelve se vuelven a habilitar (si rechaza, para
 *   poder reintentar; si resuelve, porque quien sustituye la pantalla es el
 *   wiring, no nosotros).
 *
 * Esta pantalla NO importa `activateOwnMembership`: la activación no la hace
 * el cliente. Aquí solo se espera la promesa que llega por props.
 */
export function Welcome({ profile, onAddUser, onGoToPanel }: Props) {
  /** `null` mientras no se sabe: no se puede decidir la vista sin las plazas. */
  const [seats, setSeats] = useState<number | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [leaving, setLeaving] = useState(false);
  const [leaveError, setLeaveError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    fetchSeatsUsed()
      .then((used) => {
        if (!cancelled) setSeats(used);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setLoadError(errorMessage(err instanceof Error ? err : new Error(String(err))));
      });

    return () => {
      cancelled = true;
    };
  }, []);

  /**
   * «Ir al panel». La promesa se espera entera: el error del servidor se pinta
   * aquí mismo y deja los botones listos para un segundo intento.
   */
  async function handleGoToPanel() {
    setLeaving(true);
    setLeaveError(null);

    try {
      await onGoToPanel();
    } catch (err: unknown) {
      setLeaveError(errorMessage(err instanceof Error ? err : new Error(String(err))));
    } finally {
      setLeaving(false);
    }
  }

  /**
   * Sin plazas no hay vista que decidir. Mientras llegan no se enseña ni el
   * título ni los botones: un titular de bienvenida antes de saber si el equipo
   * está lleno sería mentira la mitad de las veces.
   */
  if (loadError !== null) {
    return (
      <div className={styles.screen}>
        <div className={styles.card}>
          <p className={styles.alert} role="alert">
            {loadError}
          </p>
        </div>
      </div>
    );
  }

  if (seats === null) {
    return (
      <div className={styles.screen}>
        <div className={styles.card}>
          <p className={styles.status} role="status">
            Cargando…
          </p>
        </div>
      </div>
    );
  }

  /** El nombre lo saca `firstName`; el título, la pregunta y el contador, `welcomeView`. */
  const view = welcomeView(firstName(profile.fullName, profile.email), seats);

  return (
    <div className={styles.screen}>
      <div className={styles.card}>
        {/* Los cuatro pasos, todos cerrados: el ADMIN ya dejó la clave lista.
            El conector entre pasos lo pinta el propio item (::before), porque
            un `<ol>` solo admite `<li>`. */}
        <ol className={styles.steps} aria-label="Pasos del registro">
          {REGISTRATION_STEPS.map((label) => (
            <li key={label} className={`${styles.step} ${styles.stepDone}`}>
              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                <polyline points="22 4 12 14.01 9 11.01" />
              </svg>
              {label}
            </li>
          ))}
        </ol>

        <div className={styles.banner}>
          <span className={styles.checkRing}>
            <svg
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
              <polyline points="22 4 12 14.01 9 11.01" />
            </svg>
          </span>
          <div>
            <h1 className={styles.title}>{view.title}</h1>
            <p className={styles.subtitle}>
              Tu organización <strong>{profile.orgName}</strong> ya está activa. Antes de ir al
              panel, ¿quieres registrar más usuarios de tu equipo?
            </p>
          </div>
        </div>

        {/* El contador solo existe cuando ya hay alguien más que el ADMIN: con
            el equipo de uno, «1 de 5» no informa de nada. */}
        {view.counter !== null && (
          <div className={styles.counter} data-testid="user-counter">
            <svg
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
              <circle cx="9" cy="7" r="4" />
              <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
              <path d="M16 3.13a4 4 0 0 1 0 7.75" />
            </svg>
            {view.counter}
          </div>
        )}

        <p className={styles.question}>{view.question}</p>

        <div className={styles.buttons}>
          {/* En el límite el botón no existe: no se deshabilita, desaparece, y
              la pregunta de arriba dice por qué. */}
          {view.canAdd && (
            <button
              type="button"
              className={styles.primary}
              onClick={onAddUser}
              disabled={leaving}
            >
              <svg
                width="15"
                height="15"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
                <circle cx="8.5" cy="7" r="4" />
                <line x1="20" y1="8" x2="20" y2="14" />
                <line x1="23" y1="11" x2="17" y2="11" />
              </svg>
              Sí, añadir un usuario ahora
            </button>
          )}

          <button
            type="button"
            className={styles.secondary}
            onClick={() => {
              void handleGoToPanel();
            }}
            disabled={leaving}
          >
            Ir al panel
          </button>
        </div>

        {leaveError !== null && (
          <p className={styles.alert} role="alert">
            {leaveError}
          </p>
        )}

        <p className={styles.note}>
          Podrás invitar más usuarios desde <strong>Configuración → Gestión de usuarios</strong> en
          cualquier momento.
        </p>
      </div>
    </div>
  );
}
